// Choose a valid pixel format from known enumerators
unsigned int fmt_choice = *FUZZ_PARAM(unsigned int) % 8;
vpx_img_fmt_t fmt = VPX_IMG_FMT_I420;
switch (fmt_choice) {
  case 0: fmt = VPX_IMG_FMT_I420; break;
  case 1: fmt = VPX_IMG_FMT_I422; break;
  case 2: fmt = VPX_IMG_FMT_I444; break;
  case 3: fmt = VPX_IMG_FMT_I440; break;
  case 4: fmt = VPX_IMG_FMT_NV12; break;
  case 5: fmt = VPX_IMG_FMT_I42016; break;
  case 6: fmt = VPX_IMG_FMT_I42216; break;
  case 7: fmt = VPX_IMG_FMT_I44416; break;
}
// Dimensions kept small for fuzzer perf and bounded by API limits
unsigned int d_w = (*FUZZ_PARAM(unsigned int) % 64) + 1;  // [1..64]
unsigned int d_h = (*FUZZ_PARAM(unsigned int) % 64) + 1;  // [1..64]
// align must be <= 65536 and >0; pick small power-of-two
unsigned int align_pow = *FUZZ_PARAM(unsigned int) % 4; // 0..3
unsigned int align = 1u << align_pow; // 1,2,4,8
// Call target: pass NULL to request descriptor+storage allocation
vpx_image_t *img = vpx_img_alloc(NULL, fmt, d_w, d_h, align);
if (!img) { FUZZ_BAIL(); }
// Track allocation kind and core properties for lifetime management
FUZZ_SET_ATTR_STR(img, "alloc_kind", "alloc");
FUZZ_SET_ATTR_INT(img, "w", (int)d_w);
FUZZ_SET_ATTR_INT(img, "h", (int)d_h);
// Validation: The returned descriptor must be non-null and managed with vpx_img_free later.

// Choose a valid pixel format
unsigned int fmt_choice = *FUZZ_PARAM(unsigned int) % 8;
vpx_img_fmt_t fmt = VPX_IMG_FMT_I420;
switch (fmt_choice) {
  case 0: fmt = VPX_IMG_FMT_I420; break;
  case 1: fmt = VPX_IMG_FMT_I422; break;
  case 2: fmt = VPX_IMG_FMT_I444; break;
  case 3: fmt = VPX_IMG_FMT_I440; break;
  case 4: fmt = VPX_IMG_FMT_NV12; break;
  case 5: fmt = VPX_IMG_FMT_I42016; break;
  case 6: fmt = VPX_IMG_FMT_I42216; break;
  case 7: fmt = VPX_IMG_FMT_I44416; break;
}
// Small dimensions to keep buffer size < 2048 bytes and meet API limits
unsigned int d_w = (*FUZZ_PARAM(unsigned int) % 48) + 1;  // [1..48]
unsigned int d_h = (*FUZZ_PARAM(unsigned int) % 48) + 1;  // [1..48]
// stride_align must be <= 65536 and >0; pick small power-of-two
unsigned int stride_align_pow = *FUZZ_PARAM(unsigned int) % 4; // 0..3
unsigned int stride_align = 1u << stride_align_pow; // 1,2,4,8
// Compute a conservative buffer size upper bound:
