vpx_get_frame_buffer_cb_fn_t *get_cb = new vpx_get_frame_buffer_cb_fn_t;
*get_cb = +[](void *priv, size_t min_size, vpx_codec_frame_buffer_t *fb) -> int {
    // Enforce non-NULL fb as per API; return failure if violated
    if (!fb) return -1;
    // Keep allocations small for fuzzing; if requirement cannot be met, fail.
    const size_t kCap = 2048u;
    if (min_size == 0) min_size = 1; // allocate at least 1 byte
    if (min_size > kCap) {
